<script>
  import { onMount, tick } from "svelte";

  // Hardcoded hero playlist. Posters are frame-0 stills generated by
  // `npm run posters` (scripts/extract-posters.mjs) so we can paint
  // something instantly and cut cleanly into the real video.
  const VIDEOS = [
    { src: "/v1.mp4", poster: "/posters/v1.jpg" },
    { src: "/v2.mp4", poster: "/posters/v2.jpg" },
    { src: "/v3.mp4", poster: "/posters/v3.jpg" },
  ];

  // Musical timing: each video/poster occupies BEATS_PER_FRAME beats.
  const BPM = 120;
  const BEATS_PER_FRAME = 4;
  // Master dwell time: how long each video/poster stays on screen.
  // Videos are longer, so they're cut short at CYCLE_MS.
  const CYCLE_MS = (60000 / BPM) * BEATS_PER_FRAME; // 2000ms at 120bpm, 4 beats

  // idle | loading | ready | error
  let status = $state(VIDEOS.map(() => "idle"));
  let urls = $state(VIDEOS.map(() => null));
  // index we want showing; plays as soon as it's ready
  let active = $state(0);
  // poster currently on top while `active` is still loading
  let preview = $state(0);
  // when false we never fetch/decode; just hold the first poster
  let useVideo = true;

  let videos = [];
  let cycleTimer = null; // poster cycling while a video loads
  let advanceTimer = null; // cuts a playing video after CYCLE_MS
  let destroyed = false;

  const isReady = (i) => status[i] === "ready";

  // Download the whole file, then hand the player a blob URL. Downloading
  // fully (rather than relying on preload buffering) guarantees a clip can
  // play start-to-finish and loop without stalling.
  async function load(i, signal) {
    if (status[i] !== "idle") return;
    status[i] = "loading";
    try {
      const res = await fetch(VIDEOS[i].src, { signal });
      if (!res.ok) throw new Error(String(res.status));

      const reader = res.body?.getReader();
      let blob;
      if (reader) {
        const chunks = [];
        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          chunks.push(value);
        }
        blob = new Blob(chunks, { type: "video/mp4" });
      } else {
        blob = await res.blob();
      }

      if (destroyed) return;
      urls[i] = URL.createObjectURL(blob);
      status[i] = "ready";
      if (i === active) playActive(i);
    } catch (err) {
      if (destroyed || err?.name === "AbortError") return;
      status[i] = "error";
      if (i === active) startCycle();
    }
  }

  function startCycle() {
    clearAdvance();
    if (cycleTimer || !useVideo) return;
    cycleTimer = setInterval(() => {
      if (isReady(active)) {
        stopCycle();
        preview = active;
        return;
      }
      // Hop to the next still that hasn't finished loading.
      for (let step = 1; step <= VIDEOS.length; step++) {
        const cand = (preview + step) % VIDEOS.length;
        if (!isReady(cand)) {
          preview = cand;
          break;
        }
      }
    }, CYCLE_MS);
  }

  function stopCycle() {
    if (cycleTimer) {
      clearInterval(cycleTimer);
      cycleTimer = null;
    }
  }

  function clearAdvance() {
    if (advanceTimer) {
      clearTimeout(advanceTimer);
      advanceTimer = null;
    }
  }

  // Cut to the next item after the master dwell time.
  function advance() {
    clearAdvance();
    // Park the finished clip on its first frame so the next cut-in is clean.
    const el = videos[active];
    if (el) {
      el.pause();
      el.currentTime = 0;
    }
    active = (active + 1) % VIDEOS.length;
    if (isReady(active)) {
      playActive(active);
    } else {
      preview = active;
      startCycle();
    }
  }

  async function playActive(i = active) {
    stopCycle();
    clearAdvance();
    preview = i;
    await tick();
    const el = videos[i];
    if (!el || i !== active) return;
    el.currentTime = 0;
    try {
      await el.play();
      advanceTimer = setTimeout(advance, CYCLE_MS);
    } catch {
      // Autoplay blocked (e.g. iOS low-power) — poster stays up.
    }
  }

  // Safety net: if a clip is shorter than CYCLE_MS, advance when it ends.
  function handleEnded(i) {
    if (i !== active) return;
    advance();
  }

  onMount(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    const saveData = navigator.connection?.saveData === true;
    if (reduce || saveData) {
      useVideo = false;
      return;
    }

    const controller = new AbortController();
    // First clip gets priority; the rest fill in behind it.
    load(0, controller.signal).then(() =>
      Promise.all(VIDEOS.slice(1).map((_, idx) => load(idx + 1, controller.signal))),
    );
    if (!isReady(0)) startCycle();

    return () => {
      destroyed = true;
      controller.abort();
      stopCycle();
      clearAdvance();
      urls.forEach((u) => u && URL.revokeObjectURL(u));
    };
  });
</script>

<svelte:head>
  <link rel="preload" as="image" href={VIDEOS[0].poster} />
</svelte:head>

<div class="absolute inset-0 overflow-hidden bg-black" aria-hidden="true">
  {#each VIDEOS as video, i (video.src)}
    <!-- Poster (first frame): instant paint + fallback while loading. -->
    <img
      src={video.poster}
      alt=""
      draggable="false"
      class="absolute inset-0 h-full w-full select-none object-cover object-center"
      style="opacity: {preview === i && !isReady(i) ? 1 : 0};"
    />

    <!-- Real video: cut in over its own poster once fully downloaded. -->
    <video
      bind:this={videos[i]}
      src={urls[i]}
      muted
      playsinline
      preload="auto"
      onended={() => handleEnded(i)}
      class="absolute inset-0 h-full w-full object-cover object-center"
      style="opacity: {active === i && isReady(i) ? 1 : 0};"
    ></video>
  {/each}
</div>
